/* Linux compat firmware API for the mt76wm XNU port. Ported for mt76wm (XNU) */
#ifndef MTK_LC_FIRMWARE_H
#define MTK_LC_FIRMWARE_H

#include <linux/mtk_core.h>
#include <linux/slab.h>

/*
 * Firmware blobs come from the kext's embedded fwList (include/FwData.h,
 * generated by scripts/fw_gen.sh) and are zlib-compressed; request_firmware
 * matches on the basename and uncompresses into an IOMalloc buffer.
 * Implementation: glue/mtk_glue.c.
 */
struct firmware {
    size_t size;
    const u8 *data;
    void *priv;                 /* glue bookkeeping */
};

int request_firmware(const struct firmware **fw, const char *name,
                     struct device *dev);
int request_firmware_nowarn(const struct firmware **fw, const char *name,
                            struct device *dev);
int firmware_request_nowarn(const struct firmware **fw, const char *name,
                            struct device *dev);
void release_firmware(const struct firmware *fw);

#endif /* MTK_LC_FIRMWARE_H */
